/**
 * groq/compound does not support custom function calling, so Glint uses a
 * text protocol: the model emits tool calls as sentinel-delimited JSON blocks.
 * Sentinels are chosen to never collide with compound's internal <tool> tags
 * or with markdown code fences.
 */

export const TOOL_OPEN = "<glint:tool>";
export const TOOL_CLOSE = "</glint:tool>";

export interface ToolCall {
  tool: string;
  args: Record<string, unknown>;
  raw: string;
}

// Canonical XML form plus the legacy sentinel form — models drift between them.
const XML_RE = /<glint:tool>\s*([\s\S]*?)\s*<\/glint:tool>/g;
const SENTINEL_RE = /^[ \t]*<<<glint:tool[ \t]*\r?\n([\s\S]*?)^[ \t]*>>>(?:glint)?[ \t]*$/gm;

export function parseToolCalls(text: string): ToolCall[] {
  const calls: ToolCall[] = [];
  for (const re of [XML_RE, SENTINEL_RE]) {
    for (const match of text.matchAll(re)) {
      const parsed = parseJsonLenient(match[1].trim());
      if (parsed && typeof parsed.tool === "string") {
        calls.push({
          tool: parsed.tool,
          args: (parsed.args as Record<string, unknown>) ?? {},
          raw: match[0],
        });
      }
    }
  }
  return calls;
}

export function stripToolBlocks(text: string): string {
  return text
    .replace(XML_RE, "")
    .replace(SENTINEL_RE, "")
    .replace(/```\s*\n?\s*```/g, "")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

const OPENERS = ["<glint:tool>", "<<<glint:tool"];

/** Cut streamed text at the first tool opener so blocks never flash on screen. */
export function visiblePrefix(streamed: string): string {
  let cut = streamed.length;
  for (const opener of OPENERS) {
    const idx = streamed.indexOf(opener);
    if (idx !== -1 && idx < cut) cut = idx;
  }
  if (cut < streamed.length) return streamed.slice(0, cut);
  // Hold back a partial opener at the tail (e.g. "<glint:to" mid-stream).
  for (const opener of OPENERS) {
    for (let k = Math.min(opener.length - 1, streamed.length); k > 0; k--) {
      if (streamed.endsWith(opener.slice(0, k))) return streamed.slice(0, -k);
    }
  }
  return streamed;
}

function parseJsonLenient(body: string): { tool?: string; args?: unknown } | null {
  const cleaned = body
    .replace(/^```(?:json)?\s*/m, "")
    .replace(/```\s*$/m, "")
    .trim();
  try {
    return JSON.parse(cleaned);
  } catch {
    const start = cleaned.indexOf("{");
    if (start === -1) return null;
    let depth = 0;
    let inStr = false;
    let esc = false;
    for (let i = start; i < cleaned.length; i++) {
      const ch = cleaned[i];
      if (esc) {
        esc = false;
        continue;
      }
      if (ch === "\\") {
        esc = true;
        continue;
      }
      if (ch === '"') inStr = !inStr;
      if (inStr) continue;
      if (ch === "{") depth++;
      if (ch === "}") {
        depth--;
        if (depth === 0) {
          try {
            return JSON.parse(cleaned.slice(start, i + 1));
          } catch {
            return null;
          }
        }
      }
    }
    return null;
  }
}

export function formatToolResults(
  results: Array<{ tool: string; status: "ok" | "error"; output: string }>,
): string {
  const parts = results.map(
    (r, i) =>
      `<glint:result n="${i + 1}" tool="${r.tool}" status="${r.status}">\n${r.output}\n</glint:result>`,
  );
  return `[tool results]\n${parts.join("\n")}`;
}

