import React from "react";
import { Box, Text, useInput } from "ink";
import type { ApprovalRequest } from "../core/tools.ts";
import { theme } from "../theme.ts";

interface ApprovalProps {
  request: ApprovalRequest;
  onDecision: (approved: boolean, always: boolean) => void;
}

export function Approval({ request, onDecision }: ApprovalProps): React.ReactElement {
  useInput((input, key) => {
    if (input === "y" || key.return) onDecision(true, false);
    else if (input === "a") onDecision(true, true);
    else if (input === "n" || key.escape) onDecision(false, false);
  });

  return (
    <Box
      flexDirection="column"
      borderStyle="round"
      borderColor={theme.orange}
      paddingX={1}
      marginTop={1}
    >
      <Text bold color={theme.orange}>
        ⚠ {request.summary}
      </Text>
      <Box flexDirection="column" marginTop={1} marginBottom={1}>
        {request.detail.split("\n").slice(0, 14).map((line, i) => (
          <Text key={i} color={line.startsWith("+") ? theme.green : line.startsWith("-") ? theme.red : theme.ink}>
            {"  "}
            {line}
          </Text>
        ))}
      </Box>
      <Text color={theme.dim}>
        <Text color={theme.green} bold>y</Text>es · <Text color={theme.red} bold>n</Text>o ·{" "}
        <Text color={theme.amber} bold>a</Text>lways (this session)
      </Text>
    </Box>
  );
}

