export async function runTurn(
  state: AgentState,
  userMessage: string,
  effort: Effort,
  cb: AgentCallbacks,
  signal?: AbortSignal,
): Promise<void> {
  const config = loadConfig();
  const tools = buildTools({ onSubagent: (task) => runSubagent(task, signal) });
  const system = buildSystemPrompt({ tools, effort });
  const maxIterations = EFFORT_LEVELS[effort].maxIterations;

  state.messages.push({ role: "user", content: userMessage });
  trace("turn.user", { chars: userMessage.length, effort });
  logger.info("turn.start", { effort, history: state.messages.length });

  const turnExecuted = new Set<string>();
  let realityNudges = 0;

  for (let round = 0; round < maxIterations; round++) {
    if (signal?.aborted) throw new Error("aborted");
